from z3 import *
n = 15
X = [Int(f'x{i}') for i in range(n)]
s = Solver()
s.add(Distinct(X))
for i in range(n):
    s.add(X[i] >= 0, X[i] < n)
for d in range(1, n):
    for i in range(n - d):
        j = i + d
        for k in range(i+1, n - d):
            l = k + d
            if k != i:
                s.add(Or(X[j] - X[i] != X[l] - X[k], i != k))
print('clauses added')
print(s.check())
